DO $s$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM pg_class c JOIN pg_namespace ns ON ns.oid = c.relnamespace
  WHERE ns.nspname='public' AND c.relname='audit_logs' AND c.relrowsecurity = true;
  IF n <> 1 THEN RAISE EXCEPTION 'audit_logs relrowsecurity measured=% expected=1', n; END IF;
  SELECT count(*) INTO n FROM pg_policies WHERE schemaname='public' AND tablename='audit_logs';
  IF n <> 3 THEN RAISE EXCEPTION 'audit_logs policy count measured=% expected=3', n; END IF;
  SELECT count(*) INTO n FROM pg_policies WHERE schemaname='public' AND tablename='audit_logs'
    AND policyname IN ('audit_logs_select_member_or_admin','audit_logs_insert_member_or_admin','audit_logs_insert_tenancy_refusal');
  IF n <> 3 THEN RAISE EXCEPTION 'audit_logs expected policy names measured=% expected=3', n; END IF;
END $s$;

