  SELECT qual INTO v FROM pg_policies WHERE schemaname='public' AND tablename='audit_logs' AND cmd='SELECT';
  IF v NOT LIKE '%current_user_org_ids%' THEN RAISE EXCEPTION 'SELECT policy lost its org predicate: %', v; END IF;
